import { useEffect } from 'react';
import { useVoice, VoiceState } from '../voice/use-voice';
import '../styles/voice-launcher.css';

const DEFAULT_LABELS = {
  start: 'Talk to the assistant',
  stop: 'End the conversation',
  connecting: 'Connecting…',
  listening: 'Listening…',
  thinking: 'Thinking…',
  speaking: 'Speaking…',
  idle: 'Voice assistant',
  error: 'Connection failed — tap to try again',
  openText: 'Open text chat',
  closeText: 'Close text chat',
};

const HALO_STATE = {
  [VoiceState.CONNECTING]: 'thinking',
  [VoiceState.LISTENING]: 'listening',
  [VoiceState.PROCESSING]: 'thinking',
  [VoiceState.SPEAKING]: 'speaking',
};

/** Microphone glyph — idle (start). */
function MicGlyph() {
  return (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true"
      stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <rect x="9" y="2" width="6" height="12" rx="3" />
      <path d="M5 10a7 7 0 0 0 14 0" />
      <line x1="12" y1="19" x2="12" y2="22" />
    </svg>
  );
}

/** Speech-bubble glyph — the text-chat toggle. */
function ChatGlyph() {
  return (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true"
      stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z" />
    </svg>
  );
}

/** Sound-wave glyph — active (tap to end). Replaces the mic while a session runs. */
function ActiveGlyph() {
  return (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true"
      stroke="currentColor" strokeWidth="1.9" strokeLinecap="round">
      <line x1="4" y1="10" x2="4" y2="14" />
      <line x1="8" y1="7" x2="8" y2="17" />
      <line x1="12" y1="4" x2="12" y2="20" />
      <line x1="16" y1="7" x2="16" y2="17" />
      <line x1="20" y1="10" x2="20" y2="14" />
    </svg>
  );
}

/**
 * VoiceLauncher — a round, pulsing button that starts a live voice conversation
 * with the Altiora assistant. Mount once at the app root so it appears on every
 * page. Click to start; click again (or press Esc) to end.
 *
 * The active state stays IN PLACE — no page-dimming overlay, nothing blocks the
 * Altiora UI. While a session runs the button icon swaps to a sound-wave and a
 * semi-transparent circle around it signals activity (pulsing with the reply,
 * breathing while thinking).
 *
 * @param {object}   props
 * @param {string}   props.apiBaseUrl        REQUIRED, e.g. "/api/proxy/unpa"
 * @param {string}  [props.userId]
 * @param {Function}[props.getAuthHeaders]
 * @param {Function}[props.fetchImpl]
 * @param {string}  [props.lang]
 * @param {'bottom-right'|'bottom-left'} [props.position='bottom-right']
 * @param {number}  [props.size=60]
 * @param {object}  [props.labels]
 * @param {Function}[props.onTranscript]
 * @param {Function}[props.onError]
 */
export default function VoiceLauncher({
  apiBaseUrl, userId, getAuthHeaders, fetchImpl, lang, voice, sessionId,
  position = 'bottom-right', size = 60, labels: labelsProp, onTranscript, onError,
  onToggleTextChat, isTextChatOpen = false, onActiveChange, onState,
}) {
  const labels = { ...DEFAULT_LABELS, ...(labelsProp || {}) };
  // `sessionId` (optional): share ONE backend session with the host's text chat.
  // `voice` (optional, CS-2): the user-selected AI TTS voice.
  const { state, level, isActive, toggle, stop, explain } = useVoice({ apiBaseUrl, userId, getAuthHeaders, fetchImpl, lang, voice, sessionId, onTranscript, onError });
  // CS-4: surface the live session state to the host (for the response side panel).
  useEffect(() => { if (onActiveChange) onActiveChange(isActive); }, [isActive, onActiveChange]);
  useEffect(() => { if (onState) onState(state); }, [state, onState]);

  useEffect(() => {
    if (!isActive) return undefined;
    const onKey = (e) => { if (e.key === 'Escape') stop(); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [isActive, stop]);

  // V2: "Get help with this" — a chat-v2 anchor "?" dispatches this window event;
  // start voice and speak the anchor's explanation.
  useEffect(() => {
    const onVoiceExplain = (e) => {
      const d = e && e.detail;
      if (d && d.anchorId) explain({ id: d.anchorId, title: d.anchorTitle });
    };
    window.addEventListener('altioraVoiceExplain', onVoiceExplain);
    return () => window.removeEventListener('altioraVoiceExplain', onVoiceExplain);
  }, [explain]);

  const statusText = {
    [VoiceState.CONNECTING]: labels.connecting,
    [VoiceState.LISTENING]: labels.listening,
    [VoiceState.PROCESSING]: labels.thinking,
    [VoiceState.SPEAKING]: labels.speaking,
  }[state] || labels.idle;
  // ERROR isn't "active" (isActive excludes it, per useVoice), so without this it would
  // silently fall back to the plain "start" prompt instead of explaining the failure.
  const isError = state === VoiceState.ERROR;
  const idleLabel = isError ? labels.error : labels.start;

  const haloState = HALO_STATE[state] || 'idle';
  const amp = Math.max(0, Math.min(1, Number(level) || 0));
  // The activity circle pulses with the reply's amplitude while speaking/listening.
  const haloScale = (haloState === 'speaking' || haloState === 'listening') ? 1 + amp * 0.45 : 1;

  return (
    <div className={`fdvl-dock fdvl-dock--${position}`}>
      <button
        type="button"
        className={`fdvl-fab${isActive ? ' is-active' : ''}`}
        style={{ '--fab-size': `${size}px`, '--halo-scale': haloScale }}
        data-voice-state={state}
        onClick={toggle}
        aria-pressed={isActive}
        aria-label={isActive ? labels.stop : idleLabel}
        title={isActive ? statusText : idleLabel}
      >
        {isActive && <span className={`fdvl-halo fdvl-halo--${haloState}`} aria-hidden="true" />}
        <span className="fdvl-fab-core">{isActive ? <ActiveGlyph /> : <MicGlyph />}</span>
      </button>

      {/* Text-chat toggle — below the voice button. Host owns the window. */}
      {typeof onToggleTextChat === 'function' && (
        <button
          type="button"
          className={`fdvl-text-toggle${isTextChatOpen ? ' is-open' : ''}`}
          onClick={onToggleTextChat}
          aria-pressed={isTextChatOpen}
          aria-label={isTextChatOpen ? labels.closeText : labels.openText}
          title={isTextChatOpen ? labels.closeText : labels.openText}
        >
          <ChatGlyph />
        </button>
      )}
    </div>
  );
}
