/**
 * VoiceOrb — the animated circle shown while a voice session is live. Honest
 * state indication (listening / thinking / speaking / idle); the speaking &
 * listening states pulse with `amplitude`.
 */
export default function VoiceOrb({ state = 'idle', amplitude = 0, size = 140, label, className = '' }) {
  const amp = Math.max(0, Math.min(1, Number(amplitude) || 0));
  const pulsing = state === 'speaking' || state === 'listening';
  const scale = pulsing ? 1 + amp * 0.35 : 1;
  return (
    <div
      className={`fdvl-orb fdvl-orb--${state}${className ? ` ${className}` : ''}`}
      style={{ '--orb-size': `${size}px`, '--orb-scale': scale }}
      role="status"
      aria-label={label || state}
    >
      <span className="fdvl-orb-core" />
    </div>
  );
}
